type PremiumTabTransitionProps = {
  children: ReactNode;
  entering?: any;
  exiting?: any;
  style: any;
  transitionKey: string;
  transitioning: boolean;
};

function PremiumTabTransition({
  children,
  entering,
  exiting,
  style,
  transitionKey,
  transitioning,
}: PremiumTabTransitionProps) {
  return (
    <Animated.View
      key={transitionKey}
      collapsable={false}
      entering={entering}
      exiting={exiting}
      pointerEvents={transitioning ? 'none' : 'auto'}
      style={style}
    >
      {children}
    </Animated.View>
  );
}
