const shouldSplitPublicAvailabilityBatchError = (error: unknown) => {
  if (!error || typeof error !== 'object') {
    return false;
  }

  const candidate = error as {
    code?: unknown;
    message?: unknown;
    details?: unknown;
    hint?: unknown;
    status?: unknown;
  };
  const code = String(candidate.code ?? '').trim().toUpperCase();
  const status = Number(candidate.status);
  const description = [candidate.message, candidate.details, candidate.hint]
    .map((value) => String(value ?? '').trim().toLowerCase())
    .filter(Boolean)
    .join(' ');

  const isTransientDatabaseCode =
    code === '57014' ||
    code === '55P03' ||
    code === '40001' ||
    code === '40P01' ||
    code === '57P01' ||
    code === '57P02' ||
    code === '57P03' ||
    code.startsWith('08') ||
    code === '53200' ||
    code === '53300' ||
    code === '53400' ||
    code === '54000';
  const isTransientHttpStatus = [408, 413, 429, 502, 503, 504].includes(status);
  const describesTimeoutTransientOrSizeFailure =
    /(?:timeout|timed out|temporar|transient|network|fetch failed|connection (?:reset|closed|terminated)|service unavailable|bad gateway|gateway timeout|too many requests|rate limit|payload too large|request entity too large|batch (?:is )?too large|request size|response size|resource limit|program limit)/i.test(
      description,
    );

  return isTransientDatabaseCode || isTransientHttpStatus || describesTimeoutTransientOrSizeFailure;
};
