function BookingNextStepArrow({ reduceMotion }: { reduceMotion: boolean }) {
  const glow = useRef(new RNAnimated.Value(1)).current;
  useEffect(() => {
    if (reduceMotion) {
      glow.setValue(1);
      return;
    }
    const pulse = RNAnimated.loop(RNAnimated.sequence([
      RNAnimated.timing(glow, { toValue: 0.45, duration: 800, useNativeDriver: true, isInteraction: false }),
      RNAnimated.timing(glow, { toValue: 1, duration: 800, useNativeDriver: true, isInteraction: false }),
    ]));
    pulse.start();
    return () => pulse.stop();
  }, [glow, reduceMotion]);
  return (
    <RNAnimated.View style={[styles.frontendContinueToDayHintIcon, { opacity: glow }]}>
      <Ionicons name="arrow-down" size={20} color="#FFFFFF" />
    </RNAnimated.View>
  );
}

function ClientAccessSpinner({ tone = 'light' }: { tone?: 'light' | 'blue' }) {
  const spin = useRef(new RNAnimated.Value(0)).current;

  useEffect(() => {
    const animation = RNAnimated.loop(
      RNAnimated.timing(spin, {
        toValue: 1,
        duration: 860,
        useNativeDriver: true,
      })
    );

    animation.start();

    return () => {
      animation.stop();
    };
  }, [spin]);

  const rotate = spin.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '360deg'],
  });

  return (
    <RNAnimated.View
      style={[
        styles.clientAccessSpinner,
        tone === 'blue' && styles.clientAccessSpinnerBlue,
        { transform: [{ rotate }] },
      ]}
    />
  );
}

