const readFrontendBiometricEnabledSetting = async ({
  salonCode,
  email,
  phone,
}: {
  salonCode?: string | null;
  email?: string | null;
  phone?: string | null;
}) => {
  const scopedKey = buildFrontendBiometricEnabledKey({
    salonCode,
    email,
    phone,
  });
  if (scopedKey !== FRONTEND_BIOMETRIC_ENABLED_KEY) {
    const scopedValue = await AsyncStorage.getItem(scopedKey);
    if (scopedValue === 'true' || scopedValue === 'false') {
      return scopedValue;
    }

    // A legacy device-wide preference is reusable only for its original identity.
    const [legacySalon, legacyProfileRaw, legacyEnabled] = await Promise.all([
      AsyncStorage.getItem(FRONTEND_BIOMETRIC_SALON_CODE_KEY),
      AsyncStorage.getItem(FRONTEND_BIOMETRIC_PROFILE_KEY),
      AsyncStorage.getItem(FRONTEND_BIOMETRIC_ENABLED_KEY),
    ]);
    try {
      const legacyProfile = JSON.parse(legacyProfileRaw || 'null');
      const sameSalon = normalizeSalonCode(legacySalon || '') === normalizeSalonCode(salonCode || '');
      const sameIdentity = email?.trim()
        ? normalizeEmail(legacyProfile?.email || '') === normalizeEmail(email)
        : !!phone?.trim() && limitPhoneToTenDigits(legacyProfile?.telefono || '') === limitPhoneToTenDigits(phone);
      if (sameSalon && sameIdentity && (legacyEnabled === 'true' || legacyEnabled === 'false')) {
        await AsyncStorage.setItem(scopedKey, legacyEnabled);
        return legacyEnabled;
      }
    } catch { /* Unknown legacy identity must not enable a different account. */ }
    return null;
  }

  return null;
};
