const parseSalonMoveRoute = (note?: string | null) => {
  const value = String(note ?? '').trim();
  if (!/salone ha spostato/i.test(value)) return null;
  const operatorMatch = value.match(/Operatore:\s*([^→.]+?)\s*→\s*([^.]+)\./i);
  const timeMatch = value.match(/Orario:\s*([^→.]+?)\s*→\s*([^.]+)\./i);

  // When both time and operator changed, the start-time move is the primary
  // customer-facing event. Show that route instead of downgrading it to an
  // operator-only update.
  if (timeMatch) {
    return {
      kind: 'time' as const,
      from: timeMatch[1]?.trim() ?? '',
      to: timeMatch[2]?.trim() ?? '',
    };
  }
  if (operatorMatch) {
    return {
      kind: 'operator' as const,
      from: operatorMatch[1]?.trim() ?? '',
      to: operatorMatch[2]?.trim() ?? '',
    };
  }
  return null;
};

