const openDeviceCalendarAtDate = async (date: Date) => {
  try {
    if (Platform.OS === 'ios') {
      const appleReferenceDateMs = Date.UTC(2001, 0, 1, 0, 0, 0);
      const appleReferenceSeconds = Math.floor((date.getTime() - appleReferenceDateMs) / 1000);
      await Linking.openURL(`calshow:${appleReferenceSeconds}`);
      return true;
    }

    if (Platform.OS === 'android') {
      await Linking.openURL(`content://com.android.calendar/time/${date.getTime()}`);
      return true;
    }
  } catch {
    return false;
  }

  return false;
};

type DeviceCalendarEventPayload = Omit<Partial<Calendar.Event>, 'id' | 'organizer'>;

const ANDROID_WRITABLE_CALENDAR_ACCESS_LEVELS = new Set<Calendar.CalendarAccessLevel | undefined>([
  Calendar.CalendarAccessLevel.CONTRIBUTOR,
  Calendar.CalendarAccessLevel.EDITOR,
  Calendar.CalendarAccessLevel.OWNER,
  Calendar.CalendarAccessLevel.ROOT,
  undefined,
]);

const isWritableAndroidCalendar = (calendar: Calendar.Calendar) =>
  calendar.allowsModifications === true &&
  ANDROID_WRITABLE_CALENDAR_ACCESS_LEVELS.has(calendar.accessLevel) &&
  calendar.accessLevel !== Calendar.CalendarAccessLevel.READ &&
  calendar.accessLevel !== Calendar.CalendarAccessLevel.FREEBUSY &&
  calendar.accessLevel !== Calendar.CalendarAccessLevel.NONE;

const resolveWritableAndroidCalendarId = async () => {
  const calendars = await Calendar.getCalendarsAsync(Calendar.EntityTypes.EVENT);
  const writableCalendars = calendars.filter(isWritableAndroidCalendar);

  const preferredCalendar =
    writableCalendars.find(
      (calendar) => calendar.isPrimary && calendar.isVisible !== false && calendar.isSynced !== false
    ) ??
    writableCalendars.find((calendar) => calendar.isPrimary) ??
    writableCalendars.find((calendar) => calendar.isVisible !== false && calendar.isSynced !== false) ??
    writableCalendars.find((calendar) => calendar.isSynced !== false) ??
    writableCalendars[0];

  return preferredCalendar?.id ?? null;
};

const findExistingAndroidCalendarEventId = async (calendarId: string, eventPayload: DeviceCalendarEventPayload) => {
  if (!eventPayload.startDate || !eventPayload.endDate || !eventPayload.title) {
    return null;
  }

  const startDate = new Date(eventPayload.startDate);
  const endDate = new Date(eventPayload.endDate);
  const lookupStartDate = new Date(startDate.getTime() - 60 * 1000);
  const lookupEndDate = new Date(endDate.getTime() + 60 * 1000);
  const existingEvents = await Calendar.getEventsAsync([calendarId], lookupStartDate, lookupEndDate);

  const existingEvent = existingEvents.find((event) => {
    const eventStart = new Date(event.startDate).getTime();
    const eventEnd = new Date(event.endDate).getTime();
    return (
      event.title === eventPayload.title &&
      Math.abs(eventStart - startDate.getTime()) < 1000 &&
      Math.abs(eventEnd - endDate.getTime()) < 1000
    );
  });

  return existingEvent?.id ?? null;
};

const createAndroidCalendarEventDirectly = async (eventPayload: DeviceCalendarEventPayload) => {
  const calendarId = await resolveWritableAndroidCalendarId();
  if (!calendarId) {
    return null;
  }

  const existingEventId = await findExistingAndroidCalendarEventId(calendarId, eventPayload);
  if (existingEventId) {
    return existingEventId;
  }

  return await Calendar.createEventAsync(calendarId, eventPayload);
};

const wait = (ms: number) =>
  new Promise<void>((resolve) => {
    setTimeout(resolve, ms);
  });

type GuidedSlotStrategy = 'balanced' | 'protect_long_services' | 'fill_gaps' | 'intelligent';

type GuidedSlotBlock = {
  slots: string[];
  blockStartMinutes: number;
  blockEndMinutes: number;
};

const buildGuidedSlotBlocks = (slots: string[], intervalMinutes: number): GuidedSlotBlock[] => {
  if (!slots.length) {
    return [];
  }

  const sortedSlots = [...slots].sort((first, second) => timeToMinutes(first) - timeToMinutes(second));
  const blocks: GuidedSlotBlock[] = [];
  let currentBlock: GuidedSlotBlock | null = null;

  sortedSlots.forEach((slotTime) => {
    const slotMinutes = timeToMinutes(slotTime);

    if (
      !currentBlock ||
      slotMinutes !== timeToMinutes(currentBlock.slots[currentBlock.slots.length - 1]) + intervalMinutes
    ) {
      currentBlock = {
        slots: [slotTime],
        blockStartMinutes: slotMinutes,
        blockEndMinutes: slotMinutes,
      };
      blocks.push(currentBlock);
      return;
    }

    currentBlock.slots.push(slotTime);
    currentBlock.blockEndMinutes = slotMinutes;
  });

  return blocks;
};

const scoreGuidedSlot = ({
  slotTime,
  block,
  serviceDurationMinutes,
  intervalMinutes,
  strategy,
}: {
  slotTime: string;
  block: GuidedSlotBlock;
  serviceDurationMinutes: number;
  intervalMinutes: number;
  strategy: GuidedSlotStrategy;
}) => {
  const serviceSlots = Math.max(1, Math.ceil(serviceDurationMinutes / Math.max(intervalMinutes, 5)));
  const slotIndex = block.slots.indexOf(slotTime);
  const remainingBefore = slotIndex;
  const remainingAfter = Math.max(0, block.slots.length - slotIndex - serviceSlots);
  const fillsGapExactly = remainingBefore === 0 && remainingAfter === 0;
  const touchesEdge = remainingBefore === 0 || remainingAfter === 0;
  const createsSplit = remainingBefore > 0 && remainingAfter > 0;
  const startsAtEdge = remainingBefore === 0;
  const shortService = serviceDurationMinutes <= 30;
  const longService = serviceDurationMinutes >= 60;
  const tinyFragments = [remainingBefore, remainingAfter].filter((value) => value > 0 && value <= 1).length;
  const smallFragments = [remainingBefore, remainingAfter].filter((value) => value > 0 && value <= 2).length;
  const preservedLargestChunk = Math.max(remainingBefore, remainingAfter);
  const blockSize = block.slots.length;

  let score = 0;

  switch (strategy) {
    case 'protect_long_services':
      score += startsAtEdge ? 320 : touchesEdge ? 180 : 0;
      score += preservedLargestChunk * (longService ? 70 : 48);
      score += blockSize * (longService ? 20 : 10);
      score += remainingAfter * (longService ? 22 : 10);
      score -= fillsGapExactly ? 160 : 0;
      score -= createsSplit ? 260 : 0;
      score -= remainingBefore * 26;
      score -= tinyFragments * 40;
      score -= smallFragments * 28;
      break;
    case 'fill_gaps':
      score += fillsGapExactly ? 360 : 0;
      score += touchesEdge ? 60 : 0;
      score -= blockSize * 36;
      score -= preservedLargestChunk * 20;
      score -= createsSplit ? 14 : 0;
      score -= tinyFragments * 4;
      score -= smallFragments * 2;
      break;
    case 'balanced':
    default:
      score += fillsGapExactly ? 170 : 0;
      score += touchesEdge ? 110 : 0;
      score += longService ? blockSize * 12 : 0;
      score += shortService ? preservedLargestChunk * 10 : 0;
      score += preservedLargestChunk * 8;
      score -= createsSplit ? 70 : 0;
      score -= tinyFragments * 12;
      score -= smallFragments * 8;
      break;
  }

  score -= timeToMinutes(slotTime) / 10000;

  return score;
};

const formatAppointmentDateTimeLabel = (dateValue?: string | null, timeValue?: string | null) => {
  const rawDate = dateValue?.trim() ?? '';
  const dateMatch = rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const normalizedDate = dateMatch ? `${dateMatch[3]}-${dateMatch[2]}-${dateMatch[1]}` : rawDate;
  const normalizedTime = timeValue?.trim() ?? '';

  if (normalizedDate && normalizedTime) {
    return `${normalizedDate} alle ${normalizedTime}`;
  }

  return normalizedDate || normalizedTime || '';
};

const formatFrontendNotificationDateLabel = (dateValue?: string | null) => {
  const rawDate = dateValue?.trim() ?? '';
  const dateMatch = rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return dateMatch ? `${dateMatch[3]}-${dateMatch[2]}-${dateMatch[1]}` : rawDate;
};

const formatBookingOverviewCount = (value: number) =>
  Number.isFinite(value) && value >= 10000
    ? `${Math.floor(value / 1000)}K`
    : new Intl.NumberFormat('it-IT', { maximumFractionDigits: 0 }).format(Number.isFinite(value) ? value : 0);

const isUuidValue = (value?: string | null) => UUID_PATTERN.test((value ?? '').trim());
const normalizeCustomerNameInput = (value: string) => formatCustomerNamePart(value);
const normalizeFrontendOperatorIdentity = ({
  operatorId,
  operatorName,
}: {
  operatorId?: string | null;
  operatorName?: string | null;
}) => {
  const normalizedOperatorId = operatorId?.trim() ?? '';
  const normalizedOperatorName = operatorName?.trim() ?? '';

  if (isSalonCapacityOperatorId(normalizedOperatorId)) {
    return {
      operatorId: '',
      operatorName: '',
    };
  }

  return {
    operatorId: normalizedOperatorId,
    operatorName: normalizedOperatorName,
  };
};

const buildFrontendOperatorIdentityKey = ({
  operatorId,
  operatorName,
  operators,
}: {
  operatorId?: string | null;
  operatorName?: string | null;
  operators?: Array<{ id: string; nome: string }>;
}) => {
  const normalizedIdentity = normalizeFrontendOperatorIdentity({
    operatorId,
    operatorName,
  });

  if (normalizedIdentity.operatorId) {
    const hasCanonicalId = operators?.some(
      (item) => item.id.trim() === normalizedIdentity.operatorId
    );
    if (operators && !hasCanonicalId && normalizedIdentity.operatorName) {
      const sameNameOperators = operators.filter(
        (item) =>
          normalizeIdentityText(item.nome) ===
          normalizeIdentityText(normalizedIdentity.operatorName)
      );
      if (sameNameOperators.length === 1) {
        return `id:${sameNameOperators[0].id.trim()}`;
      }
    }
    return `id:${normalizedIdentity.operatorId}`;
  }

  const normalizedOperatorName = normalizeIdentityText(normalizedIdentity.operatorName);
  if (normalizedOperatorName) {
    return `name:${normalizedOperatorName}`;
  }

  return '';
};

const doesAnonymousAppointmentBlockFrontendService = ({
  selectedServiceName,
  existingServiceName,
  existingExplicitRole,
  services,
}: {
  selectedServiceName: string;
  existingServiceName: string;
  existingExplicitRole?: string | null;
  services: SharedService[];
}) => {
  const selectedServiceUsesOperators = doesServiceUseOperators(selectedServiceName, services);
  const existingServiceUsesOperators = doesServiceUseOperators(existingServiceName, services, existingExplicitRole);

  if (!selectedServiceUsesOperators) {
    return true;
  }

  if (!existingServiceUsesOperators) {
    return false;
  }

  const selectedCapacityId = buildSalonCapacityOperatorId(selectedServiceName, services);
  const existingCapacityId = buildSalonCapacityOperatorId(existingServiceName, services, existingExplicitRole);

  if (selectedCapacityId && existingCapacityId) {
    return selectedCapacityId === existingCapacityId;
  }

  const selectedRole = normalizeRoleName(getServiceByName(selectedServiceName, services)?.mestiereRichiesto ?? '');
  const existingRole = normalizeRoleName(
    existingExplicitRole ?? getServiceByName(existingServiceName, services)?.mestiereRichiesto ?? ''
  );

  if (!selectedRole || !existingRole) {
    return false;
  }

  return doServiceLimitScopesOverlap({
    firstServiceName: selectedServiceName,
    secondServiceName: existingServiceName,
    services,
  });
};

const getConfiguredOperatorsForFrontendService = ({
  serviceName,
  services,
  operators,
}: {
  serviceName: string;
  services: SharedService[];
  operators: PublicSalonState['operatori'];
}) =>
  getPublicEligibleOperatorsForService({
    serviceName,
    services,
    operators,
  });

const formatDisplayPersonName = (...parts: (string | null | undefined)[]) =>
  parts
    .flatMap((part) => (part ?? '').trim().split(/\s+/).filter(Boolean))
    .map((segment) => segment.charAt(0).toLocaleUpperCase('it-IT') + segment.slice(1).toLocaleLowerCase('it-IT'))
    .join(' ')
    .trim();

const formatSalonCommunicationDate = (value: string) => {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return '';
  }
  return new Intl.DateTimeFormat('it-IT', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(parsed);
};

const getSalonCommunicationMonthKey = (value: string) => {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return '';
  }
  return `${parsed.getFullYear()}-${String(parsed.getMonth() + 1).padStart(2, '0')}`;
};

type FrontendProfile = {
  nome: string;
  cognome: string;
  email: string;
  telefono: string;
  instagram: string;
};

type FrontendWebActiveSession = {
  salonCode: string;
  email: string;
  phone: string;
  passwordRequired: boolean;
};

const readFrontendWebActiveSession = (): FrontendWebActiveSession | null => {
  if (Platform.OS !== 'web' || typeof window === 'undefined') {
    return null;
  }

  try {
    const raw = window.sessionStorage.getItem(FRONTEND_WEB_ACTIVE_SESSION_KEY);
    if (!raw) {
      return null;
    }

    const parsed = JSON.parse(raw) as Partial<FrontendWebActiveSession>;
    const salonCode = normalizeSalonCode(parsed.salonCode ?? '');
    const email = normalizeEmail(parsed.email);
    const phone = limitPhoneToTenDigits(String(parsed.phone ?? ''));
    if (!salonCode || (!email && !phone)) {
      return null;
    }

    return {
      salonCode,
      email,
      phone,
      passwordRequired: parsed.passwordRequired === true,
    };
  } catch {
    return null;
  }
};

const writeFrontendWebActiveSession = (session: FrontendWebActiveSession) => {
  if (Platform.OS !== 'web' || typeof window === 'undefined') {
    return;
  }

  window.sessionStorage.setItem(
    FRONTEND_WEB_ACTIVE_SESSION_KEY,
    JSON.stringify({
      salonCode: normalizeSalonCode(session.salonCode),
      email: normalizeEmail(session.email),
      phone: limitPhoneToTenDigits(session.phone),
      passwordRequired: session.passwordRequired === true,
    })
  );
};

const clearFrontendWebActiveSession = () => {
  if (Platform.OS !== 'web' || typeof window === 'undefined') {
    return;
  }

  window.sessionStorage.removeItem(FRONTEND_WEB_ACTIVE_SESSION_KEY);
};

type FrontendAccessMode = 'login' | 'register';
type FrontendClientTabKey = 'booking' | 'notifications' | 'communications' | 'waitlist' | 'settings';
type PublicBookingDaySummaryStatus = 'available' | 'full';
type PublicBookingDaySummarySnapshot = {
  planKey: string;
  blockKey: string;
  dateValues: string[];
  statuses: Record<string, PublicBookingDaySummaryStatus>;
  confirmedAt: number;
  consistencyToken: string;
  dirtyEpoch: number;
  dirtyVersions: Record<string, number>;
};
type FrontendBookingSectionKey = 'upcoming' | 'pending' | 'accepted' | 'cancelled' | 'archive';

type FrontendBookingReadEventSnapshot = {
  version: typeof FRONTEND_REQUEST_READ_SESSIONS_VERSION;
  sectionKey: FrontendBookingSectionKey;
  requestId: string;
  appointmentGroupId: string | null;
  logicalKey: string;
  expectedStatus: string;
  expectedCancellationSource: string | null;
  expectedAppointmentDate: string;
  expectedAppointmentTime: string;
  expectedServiceName: string;
  expectedUpdatedAt: string | null;
};

type FrontendBookingReadSessionStore = Partial<
  Record<FrontendBookingSectionKey, FrontendBookingReadEventSnapshot[]>
>;

const FRONTEND_BOOKING_SECTION_KEYS: FrontendBookingSectionKey[] = [
  'upcoming',
  'pending',
  'accepted',
  'cancelled',
  'archive',
];

const isFrontendBookingSectionKey = (value: unknown): value is FrontendBookingSectionKey =>
  FRONTEND_BOOKING_SECTION_KEYS.includes(value as FrontendBookingSectionKey);

const normalizeFrontendBookingReadEventSnapshot = (
  value: unknown
): FrontendBookingReadEventSnapshot | null => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }

  const candidate = value as Partial<FrontendBookingReadEventSnapshot>;
  const sectionKey = candidate.sectionKey;
  const requestId = String(candidate.requestId ?? '').trim();
  const logicalKey = String(candidate.logicalKey ?? '').trim();
  const expectedStatus = String(candidate.expectedStatus ?? '').trim().toLowerCase();
  const expectedAppointmentDate = String(candidate.expectedAppointmentDate ?? '').trim();
  const expectedAppointmentTime = String(candidate.expectedAppointmentTime ?? '')
    .trim()
    .slice(0, 5);
  const expectedServiceName = String(candidate.expectedServiceName ?? '').trim();

  if (
    candidate.version !== FRONTEND_REQUEST_READ_SESSIONS_VERSION ||
    !isFrontendBookingSectionKey(sectionKey) ||
    !requestId ||
    !logicalKey ||
    !expectedStatus ||
    !expectedAppointmentDate ||
    !expectedAppointmentTime ||
    !expectedServiceName
  ) {
    return null;
  }

  return {
    version: FRONTEND_REQUEST_READ_SESSIONS_VERSION,
    sectionKey,
    requestId,
    appointmentGroupId: String(candidate.appointmentGroupId ?? '').trim() || null,
    logicalKey,
    expectedStatus,
    expectedCancellationSource:
      String(candidate.expectedCancellationSource ?? '').trim().toLowerCase() || null,
    expectedAppointmentDate,
    expectedAppointmentTime,
    expectedServiceName,
    expectedUpdatedAt: String(candidate.expectedUpdatedAt ?? '').trim() || null,
  };
};

const parseFrontendBookingReadEvents = (value: string | null) => {
  let parsed: unknown = [];
  try {
    parsed = value ? (JSON.parse(value) as unknown) : [];
  } catch {
    parsed = [];
  }

  if (!Array.isArray(parsed)) {
    return [] as FrontendBookingReadEventSnapshot[];
  }

  return parsed
    .map(normalizeFrontendBookingReadEventSnapshot)
    .filter((item): item is FrontendBookingReadEventSnapshot => !!item);
};

const parseFrontendBookingReadSessionStore = (value: string | null) => {
  let parsed: unknown = {};
  try {
    parsed = value ? (JSON.parse(value) as unknown) : {};
  } catch {
    parsed = {};
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return {} as FrontendBookingReadSessionStore;
  }

  const source = parsed as Record<string, unknown>;
  return FRONTEND_BOOKING_SECTION_KEYS.reduce<FrontendBookingReadSessionStore>(
    (store, sectionKey) => {
      const entries = Array.isArray(source[sectionKey])
        ? source[sectionKey]
            .map(normalizeFrontendBookingReadEventSnapshot)
            .filter((item): item is FrontendBookingReadEventSnapshot => !!item)
        : [];
      if (entries.length > 0) {
        store[sectionKey] = entries;
      }
      return store;
    },
    {}
  );
};

const buildFrontendBookingReadEventKey = (event: FrontendBookingReadEventSnapshot) =>
  [
    event.version,
    event.sectionKey,
    event.logicalKey,
    event.requestId,
    event.expectedStatus,
    event.expectedCancellationSource ?? '',
    event.expectedAppointmentDate,
    event.expectedAppointmentTime,
    event.expectedServiceName,
    event.expectedUpdatedAt ?? '',
  ].join('|');

type WaitlistRange = { key: 'day' | 'morning' | 'afternoon'; label: string; startMinute: number; endMinute: number; stepMinutes: number };
type WaitlistBookingPlan = {
  range?: WaitlistRange;
  version: 1;
  serviceId: string;
  compositionId: string | null;
  dependencyServiceId: string | null;
  label: string;
  durationMinutes: number;
  phased: boolean;
  allowSplitOperators: boolean;
  requiredRole: string | null;
  intervals: { startOffsetMinutes: number; durationMinutes: number }[];
};
const waitlistPlanSignature = (plan: WaitlistBookingPlan) => JSON.stringify([
  plan.serviceId, plan.compositionId, plan.dependencyServiceId, plan.durationMinutes,
  plan.phased, plan.allowSplitOperators, plan.requiredRole,
  plan.intervals.map(i => [i.startOffsetMinutes, i.durationMinutes]),
]);
type SlotWaitlistEntry = {
  booking_plan?: WaitlistBookingPlan | null;
  requested_duration_minutes?: number;

  id: string;
  appointment_date?: string;
  appointment_time?: string;
  display_slot_times?: string[];
  requested_service_name?: string;
  requested_operator_id?: string | null;
  requested_operator_name?: string | null;
  status?: string;
  archived_status?: string | null;
  archived_reason?: string | null;
  archived_at?: string | null;
  is_archived?: boolean | null;
  expires_at?: string | null;
  created_at?: string | null;
  updated_at?: string | null;
  notified_at?: string | null;
  viewed_by_customer?: boolean | null;
};

const isLegacyWaitlistRpcMismatch = (rpcName: string, error: unknown) => {
  if (!error || typeof error !== 'object') {
    return false;
  }

  const maybeError = error as {
    code?: string;
    message?: string;
    details?: string;
    hint?: string;
  };
  const mergedErrorText = [maybeError.code, maybeError.message, maybeError.details, maybeError.hint]
    .filter((value): value is string => typeof value === 'string' && value.trim().length > 0)
    .join(' ')
    .toLowerCase();

  if (!mergedErrorText) {
    return false;
  }

  if (mergedErrorText.includes('requested_operator_id') || mergedErrorText.includes('requested_operator_name')) {
    return false;
  }

  return (
    mergedErrorText.includes(`public.${rpcName}`) &&
    (mergedErrorText.includes('could not find the function') ||
      (mergedErrorText.includes('function') && mergedErrorText.includes('does not exist')) ||
      mergedErrorText.includes('schema cache'))
  );
};

const isSchemaCacheTransientError = (error: unknown) => {
  if (!error || typeof error !== 'object') {
    return false;
  }

  const maybeError = error as {
    code?: unknown;
    message?: unknown;
    details?: unknown;
    hint?: unknown;
  };
  const mergedErrorText = [maybeError.code, maybeError.message, maybeError.details, maybeError.hint]
    .filter((value): value is string => typeof value === 'string' && value.trim().length > 0)
    .join(' ')
    .toLowerCase();

  return (
    mergedErrorText.includes('pgrst002') ||
    mergedErrorText.includes('schema cache') ||
    mergedErrorText.includes('could not query the database for the schema cache')
  );
};

const getPublicSlotWaitlistEntriesCompat = async (params: {
  p_salon_code: string;
  p_customer_email: string;
  p_customer_phone: string;
  p_appointment_date: string;
  p_requested_service_name: string | null;
  p_requested_operator_id: string | null;
  p_requested_operator_name: string | null;
}) => {
  const response = await supabase.rpc('get_public_slot_waitlist_entries', params);

  if (!response.error || !isLegacyWaitlistRpcMismatch('get_public_slot_waitlist_entries', response.error)) {
    return response;
  }

  return supabase.rpc('get_public_slot_waitlist_entries', {
    p_salon_code: params.p_salon_code,
    p_customer_email: params.p_customer_email,
    p_customer_phone: params.p_customer_phone,
    p_appointment_date: params.p_appointment_date,
    p_requested_service_name: params.p_requested_service_name,
  });
};

