const isArchivedWaitlistRecord = (item: SlotWaitlistEntry) =>
  item.is_archived === true || String(item.archived_at ?? '').trim().length > 0;

const getArchivedWaitlistStatus = (item: SlotWaitlistEntry) =>
  String(item.archived_status ?? item.status ?? '')
    .trim()
    .toLowerCase();

const getDerivedWaitlistAlertStatus = (item: SlotWaitlistEntry) => {
  const normalizedStatus = String(item.status ?? '')
    .trim()
    .toLowerCase();

  if (isArchivedWaitlistRecord(item)) {
    return 'expired';
  }

  if (normalizedStatus === 'cancelled') {
    return normalizedStatus;
  }

  const appointmentDate = String(item.appointment_date ?? '').trim();
  const appointmentTime = String(item.appointment_time ?? '')
    .trim()
    .slice(0, 5);
  const appointmentStamp =
    appointmentDate && appointmentTime ? new Date(`${appointmentDate}T${appointmentTime}:00`).getTime() : NaN;
  const expiresStamp = item.expires_at ? Date.parse(String(item.expires_at).trim()) : NaN;
  const now = Date.now();
  const appointmentIsKnown = Number.isFinite(appointmentStamp);
  const appointmentIsPast = appointmentIsKnown && appointmentStamp <= now;
  const appointmentIsFuture = appointmentIsKnown && appointmentStamp > now;
  const wasAlreadyNotified = normalizedStatus === 'notified' || !!String(item.notified_at ?? '').trim();

  if (appointmentIsPast) {
    return 'expired';
  }

  if (wasAlreadyNotified && appointmentIsFuture) {
    return 'notified';
  }

  if (normalizedStatus === 'expired') {
    return normalizedStatus;
  }

  if (Number.isFinite(expiresStamp) && expiresStamp <= now) {
    return 'expired';
  }

  return normalizedStatus || 'waiting';
};

const buildWaitlistViewedSignature = (item: SlotWaitlistEntry) => {
  const stableAlertIdentity = [
    String(item.id ?? '').trim(),
    String(item.appointment_date ?? '').trim(),
    String(item.appointment_time ?? '')
      .trim()
      .slice(0, 5),
    String(item.requested_service_name ?? '')
      .trim()
      .toLowerCase(),
    String(item.requested_operator_id ?? '').trim(),
    String(item.requested_operator_name ?? '')
      .trim()
      .toLowerCase(),
  ]
    .filter(Boolean)
    .join('|');
  const notificationStamp = String(item.notified_at ?? item.expires_at ?? item.created_at ?? '').trim();

  return [stableAlertIdentity, notificationStamp].filter(Boolean).join(':');
};

const buildLegacyWaitlistViewedSignature = (item: SlotWaitlistEntry) =>
  [
    String(item.id ?? '').trim(),
    String(item.notified_at ?? item.updated_at ?? item.expires_at ?? item.created_at ?? '').trim(),
  ]
    .filter(Boolean)
    .join(':');

const isFrontendClientBookingPushData = (data?: Record<string, unknown> | null) => {
  if (!data) {
    return false;
  }

  const pushTarget = String(data._pushTarget ?? '')
    .trim()
    .toLowerCase();
  const pushAudience = String(data._pushAudience ?? '')
    .trim()
    .toLowerCase();
  if (pushTarget === 'owner' || pushAudience === 'auth') {
    return false;
  }

  const tokens = [
    data.type,
    data.event_type,
    data.eventType,
    data.notificationType,
    data._pushEventType,
    data.source,
    data.requestStatus,
    data.statusCode,
  ]
    .map((value) =>
      String(value ?? '')
        .trim()
        .toLowerCase()
    )
    .filter(Boolean);

  return tokens.some((token) =>
    [
      'frontend_client_status',
      'booking_request_status_changed',
      'appointment_cancelled',
      'appointment_cancelled_by_salon',
      'appointment_created',
      'appointment_created_by_salon',
      'appointment_group_created_by_salon',
      'appointment_accepted',
      'appointment_updated',
      'appointment_rescheduled',
      'appointment_rescheduled_by_salon',
      'booking_operator_change_confirmation',
      'booking_operator_change_response',
      'cancelled',
      'accepted',
      'declined',
    ].includes(token)
  );
};

