  useEffect(() => {
    let promotionBoundaryTimer: ReturnType<typeof setTimeout> | null = null;

    const syncPromotionReferenceDate = () => {
      if (promotionBoundaryTimer) {
        clearTimeout(promotionBoundaryTimer);
      }

      const now = Date.now();
      const nextReferenceDate = getTodayDateString();
      setServicePromotionReferenceDate((current) =>
        current === nextReferenceDate ? current : nextReferenceDate
      );
      promotionBoundaryTimer = setTimeout(
        syncPromotionReferenceDate,
        Math.max(250, getNextLocalServicePromotionDateBoundaryMs(now) - now + 75)
      );
    };

    const handleAppStateChange = (nextState: string) => {
      if (nextState === 'active') {
        syncPromotionReferenceDate();
      }
    };
    const handleWebResume = () => {
      if (typeof document === 'undefined' || document.visibilityState === 'visible') {
        syncPromotionReferenceDate();
      }
    };

    syncPromotionReferenceDate();
    const appStateSubscription = AppState.addEventListener('change', handleAppStateChange);
    if (Platform.OS === 'web' && typeof window !== 'undefined' && typeof document !== 'undefined') {
      window.addEventListener('focus', handleWebResume);
      window.addEventListener('pageshow', handleWebResume);
      document.addEventListener('visibilitychange', handleWebResume);
    }

    return () => {
      if (promotionBoundaryTimer) {
        clearTimeout(promotionBoundaryTimer);
      }
      appStateSubscription.remove();
      if (Platform.OS === 'web' && typeof window !== 'undefined' && typeof document !== 'undefined') {
        window.removeEventListener('focus', handleWebResume);
        window.removeEventListener('pageshow', handleWebResume);
        document.removeEventListener('visibilitychange', handleWebResume);
      }
    };
  }, []);

  useEffect(() => {
    if (Platform.OS !== 'web' || typeof window === 'undefined') {
      return;
    }

    let viewportFrame: number | null = null;
    let safeAreaProbe: HTMLDivElement | null = null;
    const readSafeAreaBottom = () => {
      if (typeof document === 'undefined') return 0;

      if (!safeAreaProbe) {
        safeAreaProbe = document.createElement('div');
        safeAreaProbe.style.position = 'fixed';
        safeAreaProbe.style.left = '0';
        safeAreaProbe.style.bottom = '0';
        safeAreaProbe.style.height = 'env(safe-area-inset-bottom)';
        safeAreaProbe.style.width = '0';
        safeAreaProbe.style.visibility = 'hidden';
        safeAreaProbe.style.pointerEvents = 'none';
        document.body.appendChild(safeAreaProbe);
      }

      const safeAreaBottom = Number.parseFloat(window.getComputedStyle(safeAreaProbe).height);
      return Number.isFinite(safeAreaBottom) ? safeAreaBottom : 0;
    };
    const updateViewportBottomInset = () => {
      if (viewportFrame !== null) {
        window.cancelAnimationFrame(viewportFrame);
      }

      viewportFrame = window.requestAnimationFrame(() => {
        viewportFrame = null;
        const viewport = window.visualViewport;
        const visualBottomInset = viewport
          ? Math.max(0, Math.ceil(window.innerHeight - viewport.height - viewport.offsetTop))
          : 0;
        const bottomInset = Math.max(visualBottomInset, readSafeAreaBottom());
        setWebViewportBottomInset(bottomInset);
      });
    };

    updateViewportBottomInset();
    window.addEventListener('resize', updateViewportBottomInset);
    window.addEventListener('orientationchange', updateViewportBottomInset);
    window.addEventListener('scroll', updateViewportBottomInset, {
      passive: true,
    });
    window.addEventListener('pageshow', updateViewportBottomInset);
    window.visualViewport?.addEventListener('resize', updateViewportBottomInset);
    window.visualViewport?.addEventListener('scroll', updateViewportBottomInset);

    return () => {
      if (viewportFrame !== null) {
        window.cancelAnimationFrame(viewportFrame);
      }
      safeAreaProbe?.remove();
      safeAreaProbe = null;
      window.removeEventListener('resize', updateViewportBottomInset);
      window.removeEventListener('orientationchange', updateViewportBottomInset);
      window.removeEventListener('scroll', updateViewportBottomInset);
      window.removeEventListener('pageshow', updateViewportBottomInset);
      window.visualViewport?.removeEventListener('resize', updateViewportBottomInset);
      window.visualViewport?.removeEventListener('scroll', updateViewportBottomInset);
    };
  }, []);

