  const customerBlockedOnlineCompositionIds = useMemo(
    () => new Set(customerOnlineBookingPolicy.blockedCompositionIds),
    [customerOnlineBookingPolicy.blockedCompositionIds]
  );

  const baseEffectiveServizi = useMemo(
    () =>
      (isCurrentWorkspaceSalon ? servizi : (publicSalonState?.servizi ?? [])).filter(
        (item) =>
          item.disponibileOnline !== false &&
          (isCurrentWorkspaceSalon ||
            (!customerBlockedOnlineServiceIds.has(item.id) &&
              !(item.compositionId && customerBlockedOnlineCompositionIds.has(item.compositionId))))
      ),
    [
      customerBlockedOnlineCompositionIds,
      customerBlockedOnlineServiceIds,
      isCurrentWorkspaceSalon,
      publicSalonState?.servizi,
      servizi,
    ]
  );
  const effectiveServizi = useMemo<SharedService[]>(
    () =>
      baseEffectiveServizi.map((service) => {
        const timing = resolveCustomerServiceTiming({
          serviceId: service.id,
          defaultDurationMinutes: service.durataMinuti ?? 60,
          defaultPhaseConfig: normalizeServicePhaseConfig(service.phaseConfig),
          overrides: customerServiceDurationOverrides,
        });
        const compositionPricing = Array.isArray(service.compositionItems)
          ? service.compositionItems.map((item) => ({
              item,
              pricing: resolveCustomerServicePrice({
                serviceId: item.serviceId,
                defaultPrice: item.price,
                overrides: customerServicePriceOverrides,
              }),
            }))
          : [];
        const pricing =
          compositionPricing.length >= 2
            ? {
                price: compositionPricing.reduce((total, entry) => total + entry.pricing.price, 0),
                customized: compositionPricing.some((entry) => entry.pricing.customized),
              }
            : resolveCustomerServicePrice({
                serviceId: service.id,
                defaultPrice: service.prezzo,
                overrides: customerServicePriceOverrides,
              });
        return {
          ...service,
          prezzo: pricing.price,
          compositionItems:
            compositionPricing.length >= 2
              ? compositionPricing.map(({ item, pricing: itemPricing }) => ({
                  ...item,
                  price: itemPricing.price,
                }))
              : service.compositionItems,
          ...(pricing.customized
            ? {
                prezzoOriginale: undefined,
                scontoAttivo: false,
                scontoValidoDal: undefined,
                scontoValidoAl: undefined,
                scontoOraDalle: undefined,
                scontoOraAlle: undefined,
                scontoGiorniSettimana: undefined,
              }
            : {}),
          durataMinuti: timing.durationMinutes,
          phaseConfig: timing.phaseConfig ?? undefined,
        };
      }),
    [baseEffectiveServizi, customerServiceDurationOverrides, customerServicePriceOverrides]
  );
  const stableFrontendServicesSignatureRef = useRef('');
